/**
 * Reads the built registry's command and index files.
 *
 * `public/r/commands.json` and `public/r/index.json` are generated by
 * `scripts/build-registry.mjs` (Task 8) — this is the single source every
 * install command shown in documentation must come from. Never type an
 * `npx shadcn add ...` command by hand in a docs page; read it from here.
 *
 * These come in as static JSON imports rather than a `node:fs` read at
 * runtime: several specimen pages that call `commandFor()` are Client
 * Components (they own interactive demo state), and a `node:fs` import
 * dragged into a client bundle fails the production build outright — a
 * chunking context that does not support `node:fs`. A JSON import has no
 * such dependency in either the server or the client bundle; the values are
 * inlined at build time either way, which is exactly what documentation
 * copy wants.
 */

import commandsJson from "@/public/r/commands.json";
import indexJson from "@/public/r/index.json";

export type RegistryCommands = Record<string, string>;

export type RegistryItem = {
  name: string;
  type: string;
  title: string;
  description: string;
  endpoint: string;
  addCommand: string;
};

export type RegistryIndex = {
  name: string;
  homepage: string;
  registryUrl: string;
  items: RegistryItem[];
};

export function readRegistryCommands(): RegistryCommands {
  return (commandsJson as RegistryCommands) ?? {};
}

export function readRegistryIndex(): RegistryIndex | null {
  return (indexJson as RegistryIndex) ?? null;
}

/** The exact install command for one registry item, or a stated fallback. */
export function commandFor(name: string): string {
  const commands = readRegistryCommands();
  return commands[name] ?? `npx shadcn@latest add ${name}`;
}
